"""Create a human-editable config draft once; never overwrite an existing file."""from __future__ import annotationsimport jsonfrom copy import deepcopyfrom pathlib import PathFORMAT_ID = "phase-search-config-draft-v1"INSTRUCTIONS = {    "purpose": "Edit config values, then tell phase-search-agent: 读取配置 JSON. This reviews the unconfirmed draft only. To conditionally confirm and enter search-agent advice after both Agent and program checks pass, say: 读取配置 JSON 并继续. This never submits or starts scientific calculations.",    "unknown_values": "Use null for unknown scalar values. Do not delete fields or invent values.",    "secrets": "Never put API keys, passwords, access tokens, private keys, or credentials in this file.",    "json": "JSONC is supported: // line comments and /* block comments */ are allowed. Keep double-quoted strings and do not use trailing commas.",}SECTION_HELP = {    "system": "First define C=(H,P,x,T,N) and each variable's role. For fixed T, supply ordered TM-containing phase references; then set configuration_space.roles.T=fixed and fixed_T_source=phase_reference. Set boundary.P and H_generation separately.",    "frozen_parameters": "Parameters that generation and search actions must never change.",    "generation_actions": "Enabled branch-generation actions and any adjustable quotas. Do not add unregistered action names.",    "calculation": "MLIP version, MC allocator, and calculation-stage settings. model_path belongs under mlip and is remote metadata; the local computer must not load a cluster model.",    "mlip": "Remote MLIP model metadata and training/validation settings. Keep cluster paths here; do not put model files or credentials in this JSON.",    "budgets": "Total and per-round limits. Keep units explicit and consistent; null means not decided, not zero.",    "dft": "DFT settings. Put user_incar_settings for single-point and relaxation tasks here when supplied. Do not assume generic atomate defaults unless explicitly selected.",    "convergence": "Human-approved convergence requirements. Energy MAE is eV/atom; hull change uses the configured hull normalization. Coverage can be evidence without being a hard condition.",    "mc_policy": "MC fidelity tiers, maximum actual MC steps, patience_steps, min_improvement and random exploration. Patience is not an MC step limit.",    "supercomputer": "Remote paths and optional scheduler metadata. Leave unavailable submit/query/cancel commands unset; the agent must not guess them.",    "storage": "Choose one local workspace_root first. Every path below is relative to it and can be edited independently. Existing files are never moved.",}FIELD_COMMENTS = {    "config.system": "体系、相空间及母结构来源。此处的目录/边界修改仍需审核和确认。",    "config.system.configuration_space": "先定义 C=(H,P,x,T,N) 的角色。默认 H/P/x/T 为 branch、N 为 branch 内搜索；固定 T 时设 roles.T=fixed、fixed_T_source=phase_reference，母结构必须含实际 TM 排列。",    "config.system.boundary": "P 的 at_x 指定端点相，intermediate 指定 0<x<1 允许相；H 由下方 H_generation 自动展开。旧式 P 列表和显式 H 仍可用。",    "config.system.H_generation": "层氧超胞生成：修改尺寸上下限和步长、最小周期距离；从推荐包含矩阵选索引 0/1，或填写自定义矩阵。多个矩阵须同时满足。",    "config.system.phase_reference_directory": "母结构公共目录。按相名自动匹配 O3.vasp、O1.vasp 等；该目录来自已提供的信息，导入前请核对。",    "config.system.phase_references": "可选的逐相文件路径；为空时根据 phase_reference_directory 和边界相名生成。",    "config.storage": "本地工作区和结果保存位置。先在配置对话中选择并确认 workspace_root，之后才生成本设置文件；所有相对路径都在此根目录内，可按需调整。不会搬动已有文件。",    "config.storage.workspace_root": "唯一工作区根目录。其他保存路径相对于此目录解析。改根目录不会自动迁移旧状态或结果。",    "config.storage.paths": "自动展示且可逐项修改的配置快照、状态、台账、结构、相图、QBC、审批和任务目录。均须为工作区内的相对路径。",    "config.calculation.mlip_version": "默认已设为 mace-mh-1；仅当你明确更换 MLIP 时才修改，并与超算端模型文件一致。",    "config.mlip.model_path": "超算端模型文件路径，仅作为元数据；本地 Agent 不加载该文件。",    "config.budgets": "计算预算与限额。注意 relative_cost 是项目内部预算单位，不等同 GPU 小时。",    "config.budgets.total_relative_cost": "本轮/运行总预算上限，单位见 cost_unit。",    "config.dft.parameters": "DFT 设置入口；可填写 single_point/relax 的 user_incar_settings。采用 atomate 默认值时也需保留 parameter_source。",    "config.mc_policy": "MC 多保真策略。max_mc_steps 是实际 MC 步数上限；patience_steps 是无改善观察步数，二者不可混用。",    "config.convergence": "人为确认的收敛阈值。MAE 使用 eV/atom；凸包变化使用项目配置的 hull 归一化口径。",    "config.supercomputer.scheduler": "超算调度命令；留空表示未配置，Agent 不会猜测 sbatch 等命令。",}def create_editable_config_json(    path, config: dict, *, bootstrap_hints=None, workspace_defaults=None) -> bool:    """Write the editable wrapper if absent; return False without touching existing content."""    if not isinstance(config, dict):        raise TypeError("config must be a JSON object")    target = Path(path)    target.parent.mkdir(parents=True, exist_ok=True)    editable_config = deepcopy(config)    if "storage" not in editable_config:        if workspace_defaults is None:            from phase_agent.configuration.session.resolve_workspace_paths import (                default_workspace_storage,            )            workspace_defaults = default_workspace_storage(target.parent)        editable_config["storage"] = deepcopy(workspace_defaults)    system = editable_config.get("system")    if isinstance(system, dict):        boundary_template = {"P": [], "H": {}, "TM_ratio": {}}        boundary = system.get("boundary")        if not isinstance(boundary, dict):            system["boundary"] = boundary_template            system.setdefault("configuration_space", {}).setdefault("roles", {})["T"] = None        else:            for key, value in boundary_template.items():                boundary.setdefault(key, value)        if system.get("system_id") == "layered_na_tm_oxide" and not (            isinstance(boundary, dict) and boundary.get("H")        ):            from phase_agent.science.structures.enumerate_layered_oxide_supercells import (                LAYERED_OXIDE_P_SMALL_RECOMMENDATIONS,            )            system.setdefault(                "H_generation",                {                    "enabled": True,                    "size_min": 4,                    "size_max": 16,                    "size_step": 1,                    "min_distance_angstrom": 2.0,                    "recommended_containment_matrices": [                        [list(row) for row in matrix]                        for matrix in LAYERED_OXIDE_P_SMALL_RECOMMENDATIONS                    ],                    "selected_recommendation_indices": [],                    "additional_containment_matrices": [],                },            )        hints = bootstrap_hints or {}        system.setdefault(            "phase_reference_directory",            hints.get("local_initial_structure_directory", ""),        )    document = {        "_format": FORMAT_ID,        "_instructions": INSTRUCTIONS,        "_section_help": SECTION_HELP,        "config": editable_config,    }    try:        with target.open("x", encoding="utf-8", newline="\n") as stream:            stream.write(_render_jsonc(document))    except FileExistsError:        return False    return Truedef _render_jsonc(value, *, level=0, path=""):    """Render JSON with explanatory // comments before selected config keys."""    indent = "  " * level    child_indent = "  " * (level + 1)    if isinstance(value, dict):        if not value:            return "{}"        lines = ["{"]        items = sorted(value.items())        for index, (key, child) in enumerate(items):            child_path = f"{path}.{key}" if path else key            comment = FIELD_COMMENTS.get(child_path)            if comment:                lines.extend(f"{child_indent}// {line}" for line in comment.splitlines())            rendered = _render_jsonc(child, level=level + 1, path=child_path)            suffix = "," if index < len(items) - 1 else ""            lines.append(f"{child_indent}{json.dumps(key, ensure_ascii=False)}: {rendered}{suffix}")        lines.append(indent + "}")        return "\n".join(lines)    if isinstance(value, list):        if not value:            return "[]"        lines = ["["]        for index, child in enumerate(value):            suffix = "," if index < len(value) - 1 else ""            lines.append(                f"{child_indent}{_render_jsonc(child, level=level + 1, path=path)}{suffix}"            )        lines.append(indent + "]")        return "\n".join(lines)    return json.dumps(value, ensure_ascii=False, indent=2)